def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    cindy_prev = None
    max_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if isinstance(prev, dict):
            bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if bid > max_prev:
                max_prev = bid
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if isinstance(prev, dict) and prev.get('bid') is not None:
                if opp.get('budget', 0) > 500:
                    cindy_prev = float(prev.get('bid'))

    units = int(supply // WATER_REQ)
    scarcity = 1.0 if units <= 1 else 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = DAILY_SALARY * (0.92 if scarcity else 0.82)
        if cindy_prev is not None:
            bid = max(bid, min(budget, cindy_prev + 3.0))
        elif max_prev > 0:
            bid = max(bid, min(budget, max_prev + 2.0))
        return float(max(0.0, min(budget, bid)))

    if hp == 3 or no_water_days == 1:
        bid = DAILY_SALARY * (0.68 if scarcity else 0.58)
        if cindy_prev is not None and cindy_prev < DAILY_SALARY * 0.95:
            bid = max(bid, cindy_prev + 1.5)
        elif max_prev > 0 and max_prev < DAILY_SALARY * 0.9:
            bid = max(bid, max_prev + 1.0)
        return float(max(0.0, min(budget, bid)))

    if scarcity:
        if cindy_prev is not None:
            if cindy_prev >= 100:
                bid = DAILY_SALARY * 0.24
            elif cindy_prev >= 70:
                bid = DAILY_SALARY * 0.34
            else:
                bid = max(DAILY_SALARY * 0.42, cindy_prev + 1.0)
        elif max_prev >= 70:
            bid = DAILY_SALARY * 0.32
        elif max_prev > 0:
            bid = max(DAILY_SALARY * 0.4, max_prev + 1.0)
        else:
            bid = DAILY_SALARY * 0.38
    else:
        bid = DAILY_SALARY * 0.22
        if urgent_opp >= 2:
            bid = DAILY_SALARY * 0.3
        if cindy_prev is not None and cindy_prev < 45:
            bid = max(bid, cindy_prev + 0.5)
        elif max_prev > 0 and max_prev < 40:
            bid = max(bid, max_prev + 0.5)

    if day >= 8 and budget > DAILY_SALARY * 6:
        bid += 4.0
    if rich_opp >= 1 and scarcity:
        bid += 2.0

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    current_day = day_context['day']
    days_remaining = EPISODE_DAYS - current_day + 1

    base_bid = DAILY_SALARY * 0.3 # Moderate base bid (45.0)

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.9 # Critical HP, bid high (135.0)
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.6 # Low HP, bid higher (90.0)

    # Budget conservation if not desperate
    if my_status['hp'] > 2 and my_status['budget'] < (base_bid * days_remaining * 0.8):
        base_bid = min(base_bid, my_status['budget'] / days_remaining * 1.2)
        base_bid = max(base_bid, DAILY_SALARY * 0.15) # Ensure a floor (22.5)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        # Filter out very low bids (like Eric's) to focus on competitive ones
        competitive_bids = [b for b in yesterday_bids if b > DAILY_SALARY * 0.1]

        if competitive_bids:
            avg_competitive_bid = sum(competitive_bids) / len(competitive_bids)

            # Adjust bid to be competitive but not overspend like opponents did
            if base_bid < avg_competitive_bid * 0.9:
                base_bid = min(DAILY_SALARY * 0.7, avg_competitive_bid * 0.95) # Cap at 105.0

            # If HP is critical, try to beat the highest bid from yesterday
            highest_prev_bid = max(yesterday_bids)
            if my_status['hp'] <= 2 and highest_prev_bid > base_bid:
                base_bid = min(DAILY_SALARY * 0.95, highest_prev_bid + 1.0) # Cap at 142.5
        else:
            # If only very low bids were seen, ensure a minimum competitive bid
            base_bid = max(base_bid, DAILY_SALARY * 0.15)

    final_bid = min(my_status['budget'], base_bid)

    # Ensure a minimum bid if budget allows
    if my_status['budget'] > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.05) # Minimum bid of 7.5

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    cindy = opponents_status.get('Cindy')

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] <= 3:
            return float(min(my_status['budget'], max_prev + 5.0))
        if cindy and cindy['alive']:
            return float(min(my_status['budget'], 60.0))
        return float(min(my_status['budget'], max_prev * 0.6))

    return float(min(my_status['budget'], 45.0))
